import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.Aev9KvMf.js";const b=JSON.parse('{"title":"医疗器械查询 · 家用设备也认\\"注册证\\"","description":"医疗器械真伪官方查询教程：NMPA 数据查询平台核对家用血压计、血糖仪等的注册证编号，区分械字号与\\"妆字号\\"\\"消字号\\"。","frontmatter":{"title":"医疗器械查询 · 家用设备也认\\"注册证\\"","issuer":"国家药品监督管理局","source_tier":"一级来源","version":"—","published":"—","source_url":"https://www.nmpa.gov.cn/datasearch/home-index.html","status":"现行服务","tags":["官方查询","医疗器械","血压计","血糖仪","防坑"],"type":"查询页","reviewed":false,"description":"医疗器械真伪官方查询教程：NMPA 数据查询平台核对家用血压计、血糖仪等的注册证编号，区分械字号与\\"妆字号\\"\\"消字号\\"。"},"headers":[],"relativePath":"query/medical-device.md","filePath":"query/medical-device.md"}'),o={name:"query/medical-device.md"};function h(l,t,n,i,s,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="医疗器械查询-·-家用设备也认-注册证" tabindex="-1">医疗器械查询 · 家用设备也认&quot;注册证&quot; <a class="header-anchor" href="#医疗器械查询-·-家用设备也认-注册证" aria-label="Permalink to &quot;医疗器械查询 · 家用设备也认&quot;注册证&quot;&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">待核验</p><p>本页由 AI 依据官方平台公开信息整理，查询步骤请以平台实际页面为准；入口改版时以药监局官网为准。</p></div><blockquote><p><strong>官方入口</strong>：国家药品监督管理局<a href="https://www.nmpa.gov.cn/datasearch/home-index.html" target="_blank" rel="noreferrer">数据查询平台</a>（选&quot;医疗器械&quot;分类：国产/进口，按一类、二类、三类分级）。· 一级来源</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p>家用血压计、血糖仪、体温计、隐形眼镜、医用口罩……只要宣称&quot;诊断或治疗&quot;用途，就必须有<strong>医疗器械注册证编号</strong>（&quot;械注准/械备案&quot;开头）。朋友圈卖的&quot;械字号面膜&quot;多数是偷换概念——真正的械字号是医用敷料类器械，查注册证一验便知。</p><h2 id="_30-秒查询步骤-待核验" tabindex="-1">30 秒查询步骤（待核验） <a class="header-anchor" href="#_30-秒查询步骤-待核验" aria-label="Permalink to &quot;30 秒查询步骤（待核验）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>怎么做</th></tr></thead><tbody><tr><td>1</td><td>打开 <a href="https://www.nmpa.gov.cn/datasearch/home-index.html" target="_blank" rel="noreferrer">NMPA 数据查询平台</a>，选&quot;医疗器械&quot;</td></tr><tr><td>2</td><td>按产品选子库（国产/进口；一类备案、二三类注册），输入产品名称或注册证编号</td></tr><tr><td>3</td><td>核对：<strong>产品名称、注册人/生产企业、有效期、适用范围</strong>与产品是否一致</td></tr></tbody></table><h2 id="结果怎么读" tabindex="-1">结果怎么读 <a class="header-anchor" href="#结果怎么读" aria-label="Permalink to &quot;结果怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>看到什么</th><th>说明</th></tr></thead><tbody><tr><td>注册证在有效期内、信息一致</td><td>正常（<a href="https://www.nmpa.gov.cn/datasearch/home-index.html" target="_blank" rel="noreferrer">数据查询平台</a>）</td></tr><tr><td>查无此证</td><td>无证&quot;医疗器械&quot;，不要买不要用</td></tr><tr><td>号称械字号但查到的是&quot;妆字号&quot;</td><td>偷换概念，按化妆品管理、不得宣称疗效</td></tr></tbody></table><h2 id="避坑要点" tabindex="-1">避坑要点 <a class="header-anchor" href="#避坑要点" aria-label="Permalink to &quot;避坑要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>骗局话术</th><th>官方依据</th></tr></thead><tbody><tr><td>&quot;量子/石墨烯理疗仪包治百病&quot;</td><td>有治疗宣称就必须有注册证；查不到即违规</td></tr><tr><td>【本站提示】家用器械按适用范围使用，用法不对照样测不准（如血压计袖带位置）</td><td>—</td></tr></tbody></table><h2 id="相关查询" tabindex="-1">相关查询 <a class="header-anchor" href="#相关查询" aria-label="Permalink to &quot;相关查询&quot;">​</a></h2><ul><li>药品：<a href="/SageRelay/query/drug.html">药品批准文号查询</a></li><li>化妆品：<a href="/SageRelay/query/cosmetics.html">化妆品备案/注册查询</a></li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>平台</td><td>国家药品监督管理局数据查询平台（一级来源）</td></tr><tr><td>入口</td><td><a href="https://www.nmpa.gov.cn/datasearch/home-index.html" target="_blank" rel="noreferrer">nmpa.gov.cn/datasearch</a>（入口以药监局官网为准）</td></tr></tbody></table>',15)])])}const m=a(o,[["render",h]]);export{b as __pageData,m as default};
